  const gross = c - employerPf - gratuity;
  const taxable = Math.max(0, gross - 75000);
  const slabs = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15],
                 [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0, prev = 0;
  for (const [upto, rate] of slabs) {
    if (taxable > prev) tax += (Math.min(taxable, upto) - prev) * rate;
    prev = upto;
  }
  if (taxable <= 1200000) tax = 0;                                  // 87A rebate
  else tax = Math.min(tax, taxable - 1200000);                      // marginal relief
  const surcharge = taxable > 2e7 ? 0.25 : taxable > 1e7 ? 0.15 : taxable > 5e6 ? 0.10 : 0;
  tax = tax * (1 + surcharge) * 1.04;
  const net = gross - employeePf - tax - 2500;
  return Math.round(net / 12 / 500) * 500;
}

// Everything downstream reads `derived`; recompute it from the canonical profile.
function computeDerived(d) {
  const salary = Number(d.profile?.current_monthly_salary) || 0;
  const monthlyExpenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
  const emergency = Number(d.emergency_fund?.current_amount) || 0;
  const totalEmi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
  const totalDebt = (d.liabilities || []).reduce((s, l) => s + (Number(l.outstanding_amount) || 0), 0);
  const totalSavingsValue = (d.savings_investments || []).reduce((s, i) => s + (Number(i.current_value) || 0), 0);
  const monthlyContrib = (d.savings_investments || []).reduce((s, i) => s + (Number(i.monthly_contribution) || 0), 0);
  const surplus = salary - totalEmi - monthlyExpenses;
  d.emergency_fund = d.emergency_fund || {};
  d.emergency_fund.has_fund = emergency > 0;
  d.emergency_fund.months_of_expenses_covered = monthlyExpenses > 0
    ? Number((emergency / monthlyExpenses).toFixed(1)) : 0;
  d.derived = {
    totalEmi, totalDebt, totalSavingsValue, monthlyContrib,
    emergencyFund: emergency,
    netWorth: totalSavingsValue + emergency - totalDebt,
    surplus,
    freeCashAfterInvesting: surplus - monthlyContrib,
    savingsRatePct: salary > 0 ? Number(((surplus / salary) * 100).toFixed(1)) : null,
  };
  return d;
}

// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
// ---- end shared helpers ----


// Gate: does this profile contain everything the report needs? If not, build a form with only the gaps.
const d = $json;
const cur = d.profile?.currency || 'INR';
const asks = [];   // { label, kind, path, placeholder, fieldType }
const seen = new Set();
const ask = (label, kind, path, placeholder, fieldType = 'text', defaultValue = '') => {
  const key = path.join('.');
  if (seen.has(key)) return;
  seen.add(key);
  asks.push({ label, kind, path, placeholder, fieldType, defaultValue });
};

for (const u of d.unreadable || []) {
  ask(u.label, u.kind, u.path,
    u.raw ? `I couldn't read "${String(u.raw).slice(0, 40)}" - try e.g. ${u.kind === 'rate' ? '8.5' : '85K, 12L or 1.5Cr'}`
          : (u.kind === 'rate' ? 'e.g. 8.5' : 'e.g. 85K, 12L or 1.5Cr'));
}

const age = Number(d.profile?.age) || 0;
if (!d.profile?.user_name) ask('Your full name', 'text', ['profile', 'user_name'], 'e.g. Priya Sharma');
if (age <= 0 || age > 110) ask('Your age', 'int', ['profile', 'age'], 'Your age in years', 'number');
if (!(Number(d.profile?.current_monthly_salary) > 0))
  ask('Monthly in-hand salary', 'amount', ['profile', 'current_monthly_salary'], 'What reaches your bank account, e.g. 1.2L');
if (!(Number(d.emergency_fund?.monthly_essential_expenses) > 0))
  ask('Monthly essential expenses', 'amount', ['emergency_fund', 'monthly_essential_expenses'], 'Rent, food, bills - not EMIs, e.g. 40K');
if (!d.goal?.description) ask('What are you saving for?', 'text', ['goal', 'description'], 'e.g. Buy a home');
if (!(Number(d.goal?.target_amount) > 0)) ask('Target amount', 'amount', ['goal', 'target_amount'], 'e.g. 80L or 1.5Cr');
const td = new Date(d.goal?.target_date);
if (!d.goal?.target_date || isNaN(td.getTime()) || td <= new Date())
  ask('Target date (must be in the future)', 'date', ['goal', 'target_date'], '', 'date');

const unreadCount = asks.length;

// Sanity check: the numbers must be possible. Money going out each month (essentials + EMIs + new
// investments) cannot exceed in-hand pay - usually a value typed into a "monthly" box by mistake,
// e.g. an FD balance entered as a monthly deposit. Ask the user to confirm, pre-filled with what they typed.
const notes = [];
const takeHome = Number(d.profile?.current_monthly_salary) || 0;
const expenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
const emi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
const contrib = (d.savings_investments || []).reduce((s, v) => s + (Number(v.monthly_contribution) || 0), 0);
const room = takeHome - expenses - emi;
if (takeHome > 0 && expenses + emi >= takeHome) {
  notes.push(`Your essentials (${esc(fmtShort(expenses, cur))}) and EMIs (${esc(fmtShort(emi, cur))}) come to more than your in-hand pay of ${esc(fmtShort(takeHome, cur))}. Please check these figures.`);
  ask('Monthly in-hand salary', 'amount', ['profile', 'current_monthly_salary'], 'e.g. 1.5L', 'text', shorthand(takeHome, cur));
  ask('Monthly essential expenses', 'amount', ['emergency_fund', 'monthly_essential_expenses'], 'Rent, food, bills - not EMIs', 'text', shorthand(expenses, cur));
} else if (takeHome > 0 && contrib > room) {
  notes.push(`These don't add up yet: you'd be investing <strong>${esc(fmtShort(contrib, cur))} a month</strong>, but after essentials and EMIs you have <strong>${esc(fmtShort(room, cur))}</strong> left from your ${esc(fmtShort(takeHome, cur))} in-hand pay.`,
             'Please check the monthly amounts below. If one of them is a one-time amount or a balance, set its monthly figure to <strong>0</strong>.');
  (d.savings_investments || []).forEach((v, i) => {
    if (Number(v.monthly_contribution) > 0) {
      ask(`${v.type} · monthly amount`, 'amount', ['savings_investments', i, 'monthly_contribution'],
          'Only what you add every month, e.g. 10K', 'text', shorthand(v.monthly_contribution, cur));
    }
  });
}

const fields = asks.map((q, i) => ({
  fieldLabel: q.label, fieldName: `fix_${i}`, fieldType: q.fieldType, requiredField: true, placeholder: q.placeholder,
  ...(q.defaultValue !== '' ? { defaultValue: q.defaultValue } : {}),
}));
if (fields.length) {
  const lines = [];
  if (unreadCount) lines.push(`${unreadCount === 1 ? 'There\'s one thing I' : 'There are ' + unreadCount + ' things I'} couldn't quite read.`);
  lines.push(...notes);
  lines.push('Fix these and I\'ll build your plan straight away.');
  fields.unshift({ fieldType: 'html', html: bubble(`Nearly there, ${esc(firstName(d.profile?.user_name))}!`, lines) });
}

return [{ json: {
  ...d,
  needs_clarification: asks.length > 0 ? 'yes' : 'no',
  missing_field_keys: asks.map(q => q.path.join('.')),
  clarification_map: asks.map((q, i) => ({ fieldName: `fix_${i}`, path: q.path, kind: q.kind })),
  clarification_form_fields: fields,
}}];

