  const mult =
    suffix === ''                                              ? 1    :
    /^(c|cr|crs|crore|crores)$/.test(suffix)                   ? 1e7  :
    /^(l|lk|lac|lacs|lakh|lakhs)$/.test(suffix)                ? 1e5  :
    /^(k|th|thousand|thousands)$/.test(suffix)                 ? 1e3  :
    /^(m|mn|million|millions)$/.test(suffix)                   ? 1e6  :
    /^(b|bn|billion|billions)$/.test(suffix)                   ? 1e9  :
    /^(pa|pm|permonth|peryear|month|year|yr|mo)$/.test(suffix) ? 1    :
    null;
  return mult === null ? null : n * mult;
}

// Optional amount: blank means 0, anything typed but unreadable means null.
function parseOptional(v) {
  if (v === null || v === undefined || String(v).trim() === '') return 0;
  return parseAmount(v);
}

// Interest rates are never scaled - "8.5%", "8.5 % p.a." and "8.5" all mean 8.5.
function parseRate(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const trim2 = x => String(Math.round(x * 100) / 100);

// Friendly short money for chat bubbles: ₹1.22L, ₹18L, ₹1.5Cr, $85K.
function fmtShort(n, cur) {
  const v = Number(n) || 0;
  const sign = v < 0 ? '-' : '';
  const a = Math.abs(v);
  if (!cur || cur === 'INR') {
    if (a >= 1e7) return sign + '₹' + trim2(a / 1e7) + 'Cr';
    if (a >= 1e5) return sign + '₹' + trim2(a / 1e5) + 'L';
    if (a >= 1e3) return sign + '₹' + trim2(a / 1e3) + 'K';
    return sign + '₹' + Math.round(a);
  }
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur,
      notation: 'compact', maximumFractionDigits: 1 }).format(v);
  } catch (e) { return cur + ' ' + Math.round(v); }
}

// Value to pre-fill an input with. Uses K/L/Cr shorthand only when it is exact,
// so re-submitting a pre-filled form never changes the stored number.
function shorthand(n, cur) {
  if (n === null || n === undefined || n === '') return '';
  const v = Number(n);
  if (!Number.isFinite(v)) return String(n);
  if (v === 0) return '0';
  if (!cur || cur === 'INR') {
    for (const [div, suf] of [[1e7, 'Cr'], [1e5, 'L'], [1e3, 'K']]) {
      if (Math.abs(v) >= div && Math.abs(Math.round((v / div) * 100) / 100 * div - v) < 0.5) return trim2(v / div) + suf;
    }
  }
  return String(Math.round(v * 100) / 100);
}

const firstName = full => String(full || '').trim().split(/\s+/)[0] || 'there';

const monthsUntil = (dateStr) => {
  const t = new Date(dateStr);
  if (!dateStr || isNaN(t.getTime())) return null;
  return Math.round((t - new Date()) / (1000 * 60 * 60 * 24 * 30.44));
};

const monthYear = (dateStr) => {
  const t = new Date(dateStr);
  return isNaN(t.getTime()) ? String(dateStr || '') :
    t.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
};

// Rough annual CTC -> monthly in-hand for India, FY 2026-27 new tax regime.
// Assumptions (shown to the user, who confirms or corrects the figure):
// basic = 40% of CTC, employer + employee PF = 12% of basic each, gratuity = 4.81% of basic,
// standard deduction 75,000, section 87A rebate up to 12L taxable, 4% cess, professional tax 2,500.
function estimateInHand(ctc, cur) {
  const c = Number(ctc) || 0;
  if (c <= 0) return null;
  if (cur && cur !== 'INR') return Math.round((c * 0.72) / 12 / 100) * 100;  // generic rough cut
  const basic = c * 0.40;
  const employerPf = basic * 0.12, gratuity = basic * 0.0481, employeePf = basic * 0.12;
  const gross = c - employerPf - gratuity;
  const taxable = Math.max(0, gross - 75000);
  const slabs = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15],
                 [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0, prev = 0;
  for (const [upto, rate] of slabs) {
    if (taxable > prev) tax += (Math.min(taxable, upto) - prev) * rate;
    prev = upto;
  }
  if (taxable <= 1200000) tax = 0;                                  // 87A rebate
  else tax = Math.min(tax, taxable - 1200000);                      // marginal relief
  const surcharge = taxable > 2e7 ? 0.25 : taxable > 1e7 ? 0.15 : taxable > 5e6 ? 0.10 : 0;
  tax = tax * (1 + surcharge) * 1.04;
  const net = gross - employeePf - tax - 2500;
  return Math.round(net / 12 / 500) * 500;
}

// Everything downstream reads `derived`; recompute it from the canonical profile.
function computeDerived(d) {
  const salary = Number(d.profile?.current_monthly_salary) || 0;
  const monthlyExpenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
  const emergency = Number(d.emergency_fund?.current_amount) || 0;
  const totalEmi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
  const totalDebt = (d.liabilities || []).reduce((s, l) => s + (Number(l.outstanding_amount) || 0), 0);
  const totalSavingsValue = (d.savings_investments || []).reduce((s, i) => s + (Number(i.current_value) || 0), 0);
  const monthlyContrib = (d.savings_investments || []).reduce((s, i) => s + (Number(i.monthly_contribution) || 0), 0);
  const surplus = salary - totalEmi - monthlyExpenses;
  d.emergency_fund = d.emergency_fund || {};
  d.emergency_fund.has_fund = emergency > 0;
  d.emergency_fund.months_of_expenses_covered = monthlyExpenses > 0
    ? Number((emergency / monthlyExpenses).toFixed(1)) : 0;
  d.derived = {
    totalEmi, totalDebt, totalSavingsValue, monthlyContrib,
    emergencyFund: emergency,
    netWorth: totalSavingsValue + emergency - totalDebt,
    surplus,
    freeCashAfterInvesting: surplus - monthlyContrib,
    savingsRatePct: salary > 0 ? Number(((surplus / salary) * 100).toFixed(1)) : null,
  };
  return d;
}

// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
// ---- end shared helpers ----


// Current allocation + the RISK PLAN. The plan is decided here, in code, so the agents follow one
// consistent rulebook: what the user said they can stomach, capped by what their goal date and
// safety net can actually afford.
const d = $('Restore User State').first().json;
const holdings = d.savings_investments || [];
const age = d.profile?.age || 30;
const cur = d.profile?.currency || 'INR';

const classify = (type) => {
  const t = String(type || '').toLowerCase();
  if (['gold', 'sgb', 'silver'].some(k => t.includes(k))) return 'gold';
  if (['etf', 'stock', 'equity', 'mutual fund', 'mf', 'index', 'nps', 'elss'].some(k => t.includes(k))) return 'equity';
  if (['fd', 'fixed deposit', 'bond', 'ppf', 'epf', 'debt', 'rd', 'recurring'].some(k => t.includes(k))) return 'debt';
  return 'cash';
};

const totals = { equity: 0, debt: 0, gold: 0, cash: 0 };
let grandTotal = 0;
holdings.forEach(h => {
  const v = Number(h.current_value) || 0;
  totals[classify(h.type)] += v;
  grandTotal += v;
});
const pct = k => grandTotal > 0 ? Number(((totals[k] / grandTotal) * 100).toFixed(1)) : 0;

const targetDate = new Date(d.goal?.target_date);
const monthsToGoal = Math.max(1, Math.round((targetDate - new Date()) / (1000 * 60 * 60 * 24 * 30.44)));
const years = monthsToGoal / 12;

// ---------------------------------------------------------------- risk plan
const LEVELS = ['Low', 'Medium', 'High'];
const stated = LEVELS.includes(d.profile?.risk_appetite) ? d.profile.risk_appetite : 'Medium';
const reasons = [];

// 1. Time horizon caps the risk the goal can carry, whatever the appetite.
const horizonCap = years < 3 ? 'Low' : years < 5 ? 'Medium' : 'High';
let effective = LEVELS[Math.min(LEVELS.indexOf(stated), LEVELS.indexOf(horizonCap))];
if (effective !== stated) {
  reasons.push(years < 3
    ? `Your goal is ${years.toFixed(1)} years away - money needed that soon should not sit in shares, so we plan at Low risk.`
    : `Your goal is ${years.toFixed(1)} years away - enough for mutual funds, but too short to ride out a deep market fall, so we plan at Medium risk.`);
}

// 2. Direct stocks need a safety net first (emergency fund, health cover, no expensive loans).
const efMonths = Number(d.emergency_fund?.months_of_expenses_covered) || 0;
const expenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
const healthCover = (d.insurance || []).filter(i => /health|medic/i.test(i.type || ''))
  .reduce((s, i) => s + (Number(i.sum_assured) || 0), 0);
const costlyLoans = (d.liabilities || []).filter(l => (Number(l.interest_rate) || 0) > 12);
const blockers = [];
if (efMonths < 3) blockers.push(`Build your emergency fund to at least 3 months of expenses (${fmtShort(expenses * 3, cur)}) - you have ${efMonths} months today.`);
if (healthCover <= 0) blockers.push('Get health insurance - one hospital bill could force you to sell shares at a loss.');
if (costlyLoans.length) blockers.push(`Clear loans above 12% interest first (${costlyLoans.map(l => `${l.type} at ${l.interest_rate}%`).join(', ')}) - they cost more than shares typically earn.`);
if (years < 3) blockers.unshift('Your goal is under 3 years away - that money should not be in shares at all, directly or through funds.');
else if (effective === 'Low') blockers.unshift('Direct stocks do not suit a Low-risk plan - equity exposure stays in diversified index funds.');
else if (years < 5) blockers.unshift('Direct stocks need at least a 5-year horizon.');
const directStocksAllowed = blockers.length === 0;

// 3. Target mix per level (percent of the portfolio).
const TARGET = {
  Low:    { equity: 15, debt: 70, gold: 10, cash: 5 },
  Medium: { equity: 50, debt: 35, gold: 10, cash: 5 },
  High:   { equity: 70, debt: 20, gold: 7,  cash: 3 },
};
let target = { ...TARGET[effective] };
if (years < 3) target = { equity: 0, debt: 85, gold: 5, cash: 10 };

const INSTRUMENTS = {
  Low:    { equity: 'Nifty 50 index fund (SIP)', debt: 'Bank FD / RD, PPF, short-term debt funds',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Savings account / liquid fund' },
  Medium: { equity: 'Nifty 50 index fund + large-cap / flexi-cap mutual funds', debt: 'PPF, FD / RD',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Liquid fund' },
  High:   { equity: 'Flexi-cap & mid-cap mutual funds + index fund', debt: 'PPF / short-duration debt funds',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Liquid fund' },
};
const instruments = { ...INSTRUMENTS[effective] };
if (years < 3) instruments.debt = 'Bank FD / RD matching your goal date, short-term debt funds';
// Share of the monthly amount that may go to hand-picked stocks (the rest of equity stays in funds).
const directStockSharePct = !directStocksAllowed ? 0 : effective === 'High' ? 25 : 10;

// Long-run planning returns per class; the plan's expected return is the blend of its mix.
const CLASS_RETURN = { equity: 11, debt: 7, gold: 8, cash: 4 };
const expectedReturn = Number(Object.keys(target).reduce((s, k) => s + target[k] / 100 * CLASS_RETURN[k], 0).toFixed(2));

const risk_plan = {
  stated_risk: stated,
  risk_source: d.profile?.risk_appetite ? 'user' : 'default',
  horizon_cap: horizonCap,
  effective_risk: effective,
  reasons,
  target_allocation: target,                 // percent; keys: equity, debt (= fixed income), gold, cash
  instruments,
  direct_stocks_allowed: directStocksAllowed,
  direct_stock_blockers: blockers,
  direct_stock_share_pct: directStockSharePct,
  stock_rules: directStocksAllowed ? {
    max_drawdown_pct: effective === 'High' && years >= 10 ? -45 : -35,  // no deeper fall than this
    max_volatility_pct: effective === 'High' ? 38 : 30,
    min_cagr_to_volatility: 0.5,                                       // growth must be >= half the swing
    max_per_sector: 2,
  } : null,
  class_return_assumptions_pct: CLASS_RETURN,
  expected_return_pct: expectedReturn,
};

return [{ json: {
  currency: cur,
  holdings: holdings.map(({ _raw, ...h }) => h),
  totalPortfolioValue: grandTotal,
  totalsByClass: totals,
  currentAllocation: {
    equity_pct: pct('equity'), debt_pct: pct('debt'),
    gold_pct: pct('gold'), cash_pct: pct('cash'),
  },
  ageBasedHeuristicEquityTargetPct: Math.max(0, Math.min(100, 100 - age)),
  monthsToGoal,
  yearsToGoal: Number(years.toFixed(1)),
  goal: d.goal,
  monthlyContribution: d.derived?.monthlyContrib || 0,
  risk_plan,
}}];

