parameters.jsCode:
// ---- shared helpers (inlined into each Code node by the builder) ----

// Accepts what people actually type: 85000, 85,000, "85K", "1.2L", "2.5 lakh", "3Cr",
// "Rs 12,00,000". Returns a number, or null if it cannot be understood - null is deliberate:
// `Check Profile Completeness` then asks the user instead of silently using 0.
function parseAmount(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let s = String(v).toLowerCase().trim();
  if (!s) return null;
  s = s.replace(/[₹$€£¥,\s_]/g, '').replace(/^(rs\.?|inr|usd|eur|gbp|aed|sgd)/, '');
  const m = s.match(/^(-?\d+(?:\.\d+)?)(.*)$/);
  if (!m) return null;
  const n = parseFloat(m[1]);
  if (!Number.isFinite(n)) return null;
  const suffix = m[2].replace(/[^a-z]/g, '');
  const mult =
    suffix === ''                                              ? 1    :
    /^(c|cr|crs|crore|crores)$/.test(suffix)                   ? 1e7  :
    /^(l|lk|lac|lacs|lakh|lakhs)$/.test(suffix)                ? 1e5  :
    /^(k|th|thousand|thousands)$/.test(suffix)                 ? 1e3  :
    /^(m|mn|million|millions)$/.test(suffix)                   ? 1e6  :
    /^(b|bn|billion|billions)$/.test(suffix)                   ? 1e9  :
    /^(pa|pm|permonth|peryear|month|year|yr|mo)$/.test(suffix) ? 1    :
    null;
  return mult === null ? null : n * mult;
}

// Optional amount: blank means 0, anything typed but unreadable means null.
function parseOptional(v) {
  if (v === null || v === undefined || String(v).trim() === '') return 0;
  return parseAmount(v);
}

// Interest rates are never scaled - "8.5%", "8.5 % p.a." and "8.5" all mean 8.5.
function parseRate(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const trim2 = x => String(Math.round(x * 100) / 100);

// Friendly short money for chat bubbles: ₹1.22L, ₹18L, ₹1.5Cr, $85K.
function fmtShort(n, cur) {
  const v = Number(n) || 0;
  const sign = v < 0 ? '-' : '';
  const a = Math.abs(v);
  if (!cur || cur === 'INR') {
    if (a >= 1e7) return sign + '₹' + trim2(a / 1e7) + 'Cr';
    if (a >= 1e5) return sign + '₹' + trim2(a / 1e5) + 'L';
    if (a >= 1e3) return sign + '₹' + trim2(a / 1e3) + 'K';
    return sign + '₹' + Math.round(a);
  }
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur,
      notation: 'compact', maximumFractionDigits: 1 }).format(v);
  } catch (e) { return cur + ' ' + Math.round(v); }
}

// Value to pre-fill an input with. Uses K/L/Cr shorthand only when it is exact,
// so re-submitting a pre-filled form never changes the stored number.
function shorthand(n, cur) {
  if (n === null || n === undefined || n === '') return '';
  const v = Number(n);
  if (!Number.isFinite(v)) return String(n);
  if (v === 0) return '0';
  if (!cur || cur === 'INR') {
    for (const [div, suf] of [[1e7, 'Cr'], [1e5, 'L'], [1e3, 'K']]) {
      if (Math.abs(v) >= div && Math.abs(Math.round((v / div) * 100) / 100 * div - v) < 0.5) return trim2(v / div) + suf;
    }
  }
  return String(Math.round(v * 100) / 100);
}

const firstName = full => String(full || '').trim().split(/\s+/)[0] || 'there';

const monthsUntil = (dateStr) => {
  const t = new Date(dateStr);
  if (!dateStr || isNaN(t.getTime())) return null;
  return Math.round((t - new Date()) / (1000 * 60 * 60 * 24 * 30.44));
};

const monthYear = (dateStr) => {
  const t = new Date(dateStr);
  return isNaN(t.getTime()) ? String(dateStr || '') :
    t.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
};

// Rough annual CTC -> monthly in-hand for India, FY 2026-27 new tax regime.
// Assumptions (shown to the user, who confirms or corrects the figure):
// basic = 40% of CTC, employer + employee PF = 12% of basic each, gratuity = 4.81% of basic,
// standard deduction 75,000, section 87A rebate up to 12L taxable, 4% cess, professional tax 2,500.
function estimateInHand(ctc, cur) {
  const c = Number(ctc) || 0;
  if (c <= 0) return null;
  if (cur && cur !== 'INR') return Math.round((c * 0.72) / 12 / 100) * 100;  // generic rough cut
  const basic = c * 0.40;
  const employerPf = basic * 0.12, gratuity = basic * 0.0481, employeePf = basic * 0.12;
  const gross = c - employerPf - gratuity;
  const taxable = Math.max(0, gross - 75000);
  const slabs = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15],
                 [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0, prev = 0;
  for (const [upto, rate] of slabs) {
    if (taxable > prev) tax += (Math.min(taxable, upto) - prev) * rate;
    prev = upto;
  }
  if (taxable <= 1200000) tax = 0;                                  // 87A rebate
  else tax = Math.min(tax, taxable - 1200000);                      // marginal relief
  const surcharge = taxable > 2e7 ? 0.25 : taxable > 1e7 ? 0.15 : taxable > 5e6 ? 0.10 : 0;
  tax = tax * (1 + surcharge) * 1.04;
  const net = gross - employeePf - tax - 2500;
  return Math.round(net / 12 / 500) * 500;
}

// Everything downstream reads `derived`; recompute it from the canonical profile.
function computeDerived(d) {
  const salary = Number(d.profile?.current_monthly_salary) || 0;
  const monthlyExpenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
  const emergency = Number(d.emergency_fund?.current_amount) || 0;
  const totalEmi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
  const totalDebt = (d.liabilities || []).reduce((s, l) => s + (Number(l.outstanding_amount) || 0), 0);
  const totalSavingsValue = (d.savings_investments || []).reduce((s, i) => s + (Number(i.current_value) || 0), 0);
  const monthlyContrib = (d.savings_investments || []).reduce((s, i) => s + (Number(i.monthly_contribution) || 0), 0);
  const surplus = salary - totalEmi - monthlyExpenses;
  d.emergency_fund = d.emergency_fund || {};
  d.emergency_fund.has_fund = emergency > 0;
  d.emergency_fund.months_of_expenses_covered = monthlyExpenses > 0
    ? Number((emergency / monthlyExpenses).toFixed(1)) : 0;
  d.derived = {
    totalEmi, totalDebt, totalSavingsValue, monthlyContrib,
    emergencyFund: emergency,
    netWorth: totalSavingsValue + emergency - totalDebt,
    surplus,
    freeCashAfterInvesting: surplus - monthlyContrib,
    savingsRatePct: salary > 0 ? Number(((surplus / salary) * 100).toFixed(1)) : null,
  };
  return d;
}

// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
// ---- end shared helpers ----


// Deterministic HTML + inline SVG charts. Prose comes from the model; every number from the computed payload.
// No external scripts or CDNs: the page renders offline, inside n8n's sandboxed completion page,
// and identically when re-opened from advice_sessions.report_json.html.
const src   = $('Assemble Report Inputs').first().json;
const r     = $json.output || {};
const snap  = src.snapshot;
const proj  = src.future_projection;
const alloc = $('Compute Allocation Metrics').first().json;
const prof  = $('Restore User State').first().json;
const cur   = src.currency || 'INR';
const plan  = src.risk_plan || alloc.risk_plan;
const mplan = src.monthly_plan || { rows: [] };

const locale = cur === 'INR' ? 'en-IN' : 'en-US';
const money = n => {
  const v = Number(n) || 0;
  try { return new Intl.NumberFormat(locale, { style: 'currency', currency: cur, maximumFractionDigits: 0 }).format(v); }
  catch (e) { return cur + ' ' + Math.round(v).toLocaleString(locale); }
};
const short = n => fmtShort(n, cur);
const pct = n => (n === null || n === undefined || !Number.isFinite(Number(n))) ? '--' : Number(n).toFixed(1) + '%';
const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const yearAt = m => { if (m === 0) return 'Now'; const t = new Date(); t.setMonth(t.getMonth() + m); return String(t.getFullYear()); };

// Validated categorical palette (adjacent-pair CVD safe); identity is always also carried by a label.
const CLASS_COLOR = { Equity: 'var(--c-equity)', Debt: 'var(--c-debt)', Gold: 'var(--c-gold)', Cash: 'var(--c-cash)' };
// Internally the "debt" asset class means FDs, PPF, EPF and bonds - money you are OWED. Readers take
// "Debt" to mean loans, so it is always shown as "Fixed income".
const CLASS_LABEL = { Equity: 'Equity', Debt: 'Fixed income', Gold: 'Gold', Cash: 'Cash' };
const canonClass = s => { const t = String(s || '').toLowerCase();
  return /equit|stock|share/.test(t) ? 'Equity' : /gold/.test(t) ? 'Gold' : /debt|fixed|bond|fd\b|deposit/.test(t) ? 'Debt' : /cash|liquid/.test(t) ? 'Cash' : s; };
const FLOW = [
  { key: 'Essentials', color: 'var(--s1)' },
  { key: 'Loan EMIs',  color: 'var(--s2)' },
  { key: 'Investing',  color: 'var(--s3)' },
  { key: 'Free cash',  color: 'var(--s4)' },
];
const STATUS = {
  good:     { color: 'var(--good)',     icon: '✓', label: 'Healthy' },
  warning:  { color: 'var(--warning)',  icon: '!', label: 'Build up' },
  critical: { color: 'var(--critical)', icon: '✕', label: 'Missing' },
};

const VERDICT = {
  on_track:  { label: 'On track',        status: 'good' },
  small_gap: { label: 'Slightly behind', status: 'warning' },
  large_gap: { label: 'Significant gap', status: 'critical' },
}[proj.verdict] || { label: 'Reviewed', status: 'warning' };

// ---------- chart builders ----------

// Progress ring for the hero.
function ring(p) {
  const R = 52, C = 2 * Math.PI * R, v = clamp(Number(p) || 0, 0, 100);
  return `<svg class="ring" viewBox="0 0 128 128" role="img" aria-label="${v.toFixed(0)}% of goal projected">
    <circle cx="64" cy="64" r="${R}" class="ring-track"/>
    <circle cx="64" cy="64" r="${R}" class="ring-fill" style="stroke:${STATUS[VERDICT.status].color}"
      stroke-dasharray="${(C * v / 100).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 64 64)"><title>${v.toFixed(1)}% of target projected</title></circle>
    <text x="64" y="62" class="ring-num">${v.toFixed(0)}%</text>
    <text x="64" y="82" class="ring-sub">of goal</text>
  </svg>`;
}

// Horizontal 100% stacked bar in HTML (responsive; text never distorts).
function stackBar(segs, total) {
  const t = total || segs.reduce((s, x) => s + x.value, 0) || 1;
  return `<div class="stack">${segs.filter(s => s.value > 0).map(s =>
    `<span style="width:${(s.value / t * 100).toFixed(2)}%;background:${s.color}" title="${esc(s.key)}: ${esc(money(s.value))} (${(s.value / t * 100).toFixed(0)}%)"></span>`).join('')}</div>`;
}
const legend = (segs, total) => `<ul class="legend">${segs.map(s => `
  <li><i style="background:${s.color}"></i><span class="lg-key">${esc(s.key)}</span>
  <span class="lg-val">${esc(money(s.value))}</span><span class="lg-pct">${total > 0 ? (s.value / total * 100).toFixed(0) + '%' : ''}</span></li>`).join('')}</ul>`;

// Donut of current allocation.
function donut(parts, centerTop, centerBottom) {
  const R = 70, C = 2 * Math.PI * R, total = parts.reduce((s, p) => s + p.value, 0);
  if (!total) return `<div class="empty">No investments recorded yet</div>`;
  let off = 0;
  const arcs = parts.filter(p => p.value > 0).map(p => {
    const len = p.value / total * C;
    const gap = parts.filter(x => x.value > 0).length > 1 ? 2 : 0;
    const el = `<circle cx="90" cy="90" r="${R}" class="donut-seg" style="stroke:${p.color}"
      stroke-dasharray="${Math.max(0.1, len - gap).toFixed(2)} ${C.toFixed(2)}" stroke-dashoffset="${(-off).toFixed(2)}"
      transform="rotate(-90 90 90)"><title>${esc(p.key)}: ${esc(money(p.value))} (${(p.value / total * 100).toFixed(1)}%)</title></circle>`;
    off += len;
    return el;
  }).join('');
  return `<svg class="donut" viewBox="0 0 180 180" role="img" aria-label="Current asset allocation">
    <circle cx="90" cy="90" r="${R}" class="donut-track"/>${arcs}
    <text x="90" y="86" class="donut-num">${esc(centerTop)}</text>
    <text x="90" y="106" class="donut-sub">${esc(centerBottom)}</text></svg>`;
}

// Line chart: projected corpus at today's contribution vs the contribution that hits the goal, with the target line.
function projectionChart() {
  const s = proj.series || [];
  if (s.length < 2) return '';
  const W = 720, H = 300, L = 64, R = 160, T = 18, B = 36;
  const maxY = Math.max(proj.target_amount, ...s.map(p => Math.max(p.current_path, p.required_path))) * 1.1 || 1;
  const maxM = s[s.length - 1].month || 1;
  const x = m => L + (m / maxM) * (W - L - R);
  const y = v => T + (1 - v / maxY) * (H - T - B);

  const ticks = [0, 0.25, 0.5, 0.75, 1].map(f => f * maxY);
  const grid = ticks.map(v => `<line x1="${L}" x2="${W - R}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" class="grid"/>
    <text x="${L - 8}" y="${(y(v) + 4).toFixed(1)}" class="axis" text-anchor="end">${esc(short(v))}</text>`).join('');
  // at most ~8 year labels; the last point is always labelled and never crowds its neighbour
  const step = Math.max(1, Math.ceil(s.length / 8));
  const shown = [];
  for (let i = 0; i < s.length; i += step) shown.push(i);
  if (shown[shown.length - 1] !== s.length - 1) {
    if (s.length - 1 - shown[shown.length - 1] < step * 0.75) shown[shown.length - 1] = s.length - 1; else shown.push(s.length - 1);
  }
  const xLabels = shown.map(i => s[i]).map(p => `<text x="${x(p.month).toFixed(1)}" y="${H - 12}" class="axis" text-anchor="middle">${
    yearAt(p.month)}</text>`).join('');

  const path = key => s.map((p, i) => `${i ? 'L' : 'M'}${x(p.month).toFixed(1)},${y(p[key]).toFixed(1)}`).join(' ');
  const area = `${path('current_path')} L${x(maxM).toFixed(1)},${y(0).toFixed(1)} L${x(0).toFixed(1)},${y(0).toFixed(1)} Z`;
  // visible markers only when sparse; dense series keep invisible hover targets with the same tooltips
  const dense = s.length > 12;
  const dots = key => s.map(p => `<circle cx="${x(p.month).toFixed(1)}" cy="${y(p[key]).toFixed(1)}" r="${dense ? 6 : 4}" class="dot${dense ? ' hit' : ''}" style="fill:${key === 'current_path' ? 'var(--s1)' : 'var(--s3)'}">
      <title>${yearAt(p.month)} · ${key === 'current_path' ? 'At your current SIP' : 'At the required SIP'}: ${esc(money(p[key]))}</title></circle>`).join('');

  const last = s[s.length - 1];
  const endLabel = (yPix, text, color) =>
    `<text x="${W - R + 8}" y="${(yPix + 4).toFixed(1)}" class="end-label" style="fill:var(--ink)"><tspan style="fill:${color}">●</tspan> ${esc(text)}</text>`;
  // stack the three end labels top-down so they never collide
  const labels = [
    { v: last.current_path, t: short(last.current_path) + ' today\'s pace', c: 'var(--s1)' },
    { v: last.required_path, t: short(last.required_path) + ' needed pace', c: 'var(--s3)' },
    { v: proj.target_amount, t: 'Target ' + short(proj.target_amount), c: 'var(--muted)' },
  ].sort((a, b) => b.v - a.v);
  let prevY = -Infinity;
  const endLabels = labels.map(l => { const yy = Math.max(y(l.v), prevY + 16); prevY = yy; return endLabel(yy, l.t, l.c); }).join('');

  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Projected savings path versus target">
    ${grid}
    <line x1="${L}" x2="${W - R}" y1="${y(proj.target_amount).toFixed(1)}" y2="${y(proj.target_amount).toFixed(1)}" class="target-line"/>
    <path d="${area}" class="area"/>
    <path d="${path('required_path')}" class="line" style="stroke:var(--s3)"/>
    <path d="${path('current_path')}" class="line" style="stroke:var(--s1)"/>
    ${dots('required_path')}${dots('current_path')}
    ${xLabels}${endLabels}
  </svg>`;
}

// Meter card for the safety-net check.
function meter(title, valueText, ratio, status, note, label) {
  const st = STATUS[status];
  return `<div class="meter">
    <div class="meter-head"><span class="meter-title">${esc(title)}</span>
      <span class="badge" style="--b:${st.color}"><b>${st.icon}</b> ${esc(label || st.label)}</span></div>
    <div class="meter-value">${esc(valueText)}</div>
    <div class="meter-track"><span style="width:${(clamp(ratio, 0, 1) * 100).toFixed(1)}%;background:${st.color}"></span></div>
    <div class="meter-note">${esc(note)}</div>
  </div>`;
}

// ---------- data for the charts ----------
const salary = Number(snap.monthly_salary) || 0;
const flowVals = [
  Number(snap.monthly_expenses) || 0,
  Number(snap.total_emi) || 0,
  Number(snap.monthly_investing) || 0,
  Math.max(0, Number(snap.free_cash_after_investing) || 0),
];
const flowSegs = FLOW.map((f, i) => ({ ...f, value: flowVals[i] }));
const outflow = flowVals[0] + flowVals[1] + flowVals[2];
const overspend = outflow - salary;

// Every percentage is a share of in-hand pay. If money going out exceeds pay, the bar grows past a
// marked "in-hand pay" line and the excess is shown as a shortfall - never silently rescaled.
function cashFlowChart() {
  const scale = Math.max(salary, outflow) || 1;
  const segs = flowSegs.filter(f => f.value > 0);
  const bar = `<div class="stack">${segs.map(f =>
    `<span style="width:${(f.value / scale * 100).toFixed(2)}%;background:${f.color}" title="${esc(f.key)}: ${esc(money(f.value))} (${salary ? (f.value / salary * 100).toFixed(0) : '--'}% of in-hand pay)"></span>`).join('')}</div>`;
  const marker = overspend > 0 ? `<div class="pay-marker" style="left:${(salary / scale * 100).toFixed(2)}%"><span>In-hand pay ${esc(short(salary))}</span></div>` : '';
  const items = flowSegs.map(f => ({ ...f }));
  if (overspend > 0) items[3] = { key: 'Shortfall', value: overspend, color: 'var(--critical)' };
  return `<div class="flow-wrap">${bar}${marker}</div>${legend(items, salary)}`;
}

const tbc = snap.totals_by_class || alloc.totalsByClass || {};
const emergencyAmt = Number(snap.emergency_fund_amount) || 0;
const classParts = [
  { key: 'Equity', value: Number(tbc.equity) || 0, color: CLASS_COLOR.Equity },
  { key: 'Fixed income (FD/PPF)', value: Number(tbc.debt) || 0, color: CLASS_COLOR.Debt },
  { key: 'Gold',   value: Number(tbc.gold) || 0,   color: CLASS_COLOR.Gold },
  { key: 'Cash',   value: Number(tbc.cash) || 0,   color: CLASS_COLOR.Cash },
];
const ownParts = classParts.map(p => p.key === 'Cash'
  ? { ...p, key: 'Cash & emergency fund', value: p.value + emergencyAmt } : p);
const ownTotal = ownParts.reduce((s, p) => s + p.value, 0);
const loans = (prof.liabilities || []).map(l => ({
  key: `${l.type} @ ${l.interest_rate ?? '?'}%`, value: Number(l.outstanding_amount) || 0,
  rate: Number(l.interest_rate) || 0, emi: Number(l.emi) || 0,
  color: (Number(l.interest_rate) || 0) > 12 ? 'var(--critical)' : 'var(--neutral)',
}));
const oweTotal = loans.reduce((s, l) => s + l.value, 0);
const scaleMax = Math.max(ownTotal, oweTotal) || 1;

const currentByClass = {
  Equity: alloc.currentAllocation.equity_pct, Debt: alloc.currentAllocation.debt_pct,
  Gold: alloc.currentAllocation.gold_pct, Cash: alloc.currentAllocation.cash_pct,
};
const advice = (r.allocation_advice || []);
const allocBars = ['Equity', 'Debt', 'Gold', 'Cash'].map(k => {
  const a = advice.find(x => canonClass(x.asset_class) === k);
  const now = Number(currentByClass[k]) || 0, to = Number(plan.target_allocation[k === 'Debt' ? 'debt' : k.toLowerCase()]);
  return `<div class="ab-row">
    <div class="ab-key"><i style="background:${CLASS_COLOR[k]}"></i>${CLASS_LABEL[k]}</div>
    <div class="ab-bars">
      <div class="ab-bar now" title="${CLASS_LABEL[k]} now: ${pct(now)}"><span style="width:${clamp(now, 0, 100)}%;background:${CLASS_COLOR[k]}"></span><em>${pct(now)}</em></div>
      ${to !== null ? `<div class="ab-bar to" title="${CLASS_LABEL[k]} suggested: ${pct(to)}"><span style="width:${clamp(to, 0, 100)}%;background:${CLASS_COLOR[k]}"></span><em>${pct(to)}</em></div>` : ''}
    </div></div>`;
}).join('');

// Safety net meters
const efMonths = Number(snap.months_of_expenses_covered) || 0;
const termRec = Number(snap.recommended_term_cover) || 0, term = Number(snap.term_cover) || 0;
const healthRec = Number(snap.recommended_health_cover) || 0, health = Number(snap.health_cover) || 0;
const dti = Number(snap.debt_to_income_pct) || 0;
const meters = [
  meter('Emergency fund', `${efMonths} of 6 months`, efMonths / 6,
    efMonths >= 6 ? 'good' : efMonths > 0 ? 'warning' : 'critical',
    efMonths >= 6 ? 'Six months of essentials covered.' : `Target ${short(snap.emergency_fund_target)} - ${short(Math.max(0, snap.emergency_fund_target - emergencyAmt))} to go.`),
  meter('Term life cover', term ? short(term) : 'None', termRec ? term / termRec : 0,
    term >= termRec && term > 0 ? 'good' : term > 0 ? 'warning' : 'critical',
    `Guide: about 10× annual income (${short(termRec)}).`),
  meter('Health cover', health ? short(health) : 'None', healthRec ? health / healthRec : (health > 0 ? 1 : 0),
    health > 0 && (!healthRec || health >= healthRec) ? 'good' : health > 0 ? 'warning' : 'critical',
    healthRec ? `Guide: at least ${short(healthRec)} for a family in a metro.` : 'Check the cover suits local hospital costs.'),
  meter('EMIs vs take-home', pct(dti), dti / 60,
    dti <= 30 ? 'good' : dti <= 40 ? 'warning' : 'critical',
    dti <= 40 ? 'Within the 40% comfort line.' : 'Above the 40% comfort line.',
    dti <= 30 ? 'Healthy' : dti <= 40 ? 'Watch it' : 'Too high'),
].join('');
const metersHtml = meters;

// ---------- prose blocks ----------
const actions = (r.priority_actions || []).map((a, i) => `
  <li class="action"><span class="rank">${i + 1}</span><div>
    <div class="action-title">${esc(a.title)}</div>
    <div class="action-why">${esc(a.why)}</div>
    <div class="action-how">${esc(a.how)}</div></div></li>`).join('');

const allocRows = ['Equity', 'Debt', 'Gold', 'Cash'].map(k => {
  const a = advice.find(x => canonClass(x.asset_class) === k) || {};
  const now = currentByClass[k] ?? 0, to = Number(plan.target_allocation[k === 'Debt' ? 'debt' : k.toLowerCase()]) || 0;
  const delta = Number((to - now).toFixed(1));
  const cls = delta > 0.5 ? 'up' : delta < -0.5 ? 'down' : 'flat';
  const arrow = delta > 0.5 ? '&#9650;' : delta < -0.5 ? '&#9660;' : '&#8212;';
  return `<tr><td>${esc(CLASS_LABEL[k] || a.asset_class)}</td><td class="num">${pct(now)}</td><td class="num">${pct(to)}</td>
    <td class="num ${cls}">${arrow} ${Math.abs(delta).toFixed(1)}%</td><td class="rationale">${esc(a.rationale || plan.instruments[k === 'Debt' ? 'debt' : k.toLowerCase()])}</td></tr>`;
}).join('');

// The model proposes, the code disposes: every name must pass the risk plan's rules.
const rules = plan.stock_rules;
const dropped = [];
let shortlist = [];
if (plan.direct_stocks_allowed) {
  const perSector = {};
  for (const st of (r.equity_shortlist || [])) {
    const dd = Number(st.max_drawdown_pct), vol = Number(st.annualized_volatility_pct), cagr = Number(st.five_year_cagr_pct);
    const why = [];
    if (!Number.isFinite(dd) || !Number.isFinite(vol) || !Number.isFinite(cagr)) why.push('figures missing from the dataset');
    else {
      if (-Math.abs(dd) < rules.max_drawdown_pct) why.push(`worst fall ▼${Math.abs(dd).toFixed(1)}% is deeper than your ▼${Math.abs(rules.max_drawdown_pct)}% limit`);
      if (vol > rules.max_volatility_pct) why.push(`swings of ${vol.toFixed(1)}% a year exceed your ${rules.max_volatility_pct}% limit`);
      if (cagr < vol * rules.min_cagr_to_volatility) why.push(`growth of ${cagr.toFixed(1)}% a year is too low for ${vol.toFixed(1)}% swings`);
    }
    const sec = String(st.sector || '').toLowerCase();
    if (!why.length && (perSector[sec] || 0) >= rules.max_per_sector) why.push(`already ${rules.max_per_sector} picks from ${st.sector}`);
    if (why.length) dropped.push({ ...st, why });
    else { shortlist.push(st); perSector[sec] = (perSector[sec] || 0) + 1; }
  }
} else {
  dropped.push(...(r.equity_shortlist || []).map(st => ({ ...st, why: ['direct stocks are not part of your plan yet'] })));
}
r.equity_shortlist = shortlist;                        // what gets stored and shown
r.equity_shortlist_removed = dropped.map(x => ({ symbol: x.symbol, why: x.why }));
const stockMonthly = (mplan.rows.find(x => x.bucket === 'Direct stocks') || {}).amount || 0;
const maxCagr = Math.max(1, ...shortlist.map(s => Math.abs(Number(s.five_year_cagr_pct) || 0)));
const equityRows = shortlist.map(s => `<tr>
    <td><strong>${esc(s.symbol)}</strong><div class="sub">${esc(s.company_name)}</div></td>
    <td>${esc(s.sector)}</td>
    <td class="num">${s.five_year_cagr_pct != null ? `<span class="mini"><span style="width:${(Math.abs(s.five_year_cagr_pct) / maxCagr * 100).toFixed(0)}%"></span></span>${pct(s.five_year_cagr_pct)}` : '--'}</td>
    <td class="num">${s.annualized_volatility_pct != null ? pct(s.annualized_volatility_pct) : '--'}</td>
    <td class="num down" title="Largest drop from a peak to a later low in the 5-year window">${s.max_drawdown_pct != null ? '▼ ' + Math.abs(Number(s.max_drawdown_pct)).toFixed(1) + '%' : '--'}
      <div class="sub">₹10,000 → ${esc(money(10000 * (1 - Math.abs(Number(s.max_drawdown_pct)) / 100)))}</div></td>
    <td class="rationale">${esc(s.rationale)}</td></tr>`).join('');

const LEVEL_COLOR = { Low: 'var(--c-debt)', Medium: 'var(--s1)', High: 'var(--s2)' };
const levelPills = ['Low', 'Medium', 'High'].map(l => `<div class="lvl${l === plan.effective_risk ? ' on' : ''}" style="--lc:${LEVEL_COLOR[l]}">
    <div class="lvl-name">${l}</div><div class="lvl-sub">${l === 'Low' ? 'FDs, PPF, index fund' : l === 'Medium' ? 'Mostly mutual funds' : 'Funds + direct stocks'}</div>
