  .caveat { font-size: 12.5px; color: var(--ink-2); background: var(--surface-2); border-left: 3px solid var(--warning); padding: 10px 14px; border-radius: 0 6px 6px 0; margin: 14px 0 0; }
  .disclaimer { margin-top: 28px; padding: 14px 16px; border-left: 3px solid var(--border); background: var(--surface); font-size: 13px; color: var(--ink-2); border-radius: 0 8px 8px 0; }
  details.data { margin-top: 12px; font-size: 13px; } details.data summary { cursor: pointer; color: var(--ink-2); }
  @media (max-width: 640px) {
    .hero { flex-direction: column; align-items: flex-start; }
    .alloc, .two-col { grid-template-columns: 1fr; }
    .donut { margin: 0 auto; display: block; }
    .debt-row { grid-template-columns: 1fr 80px; } .debt-row .debt-bar { grid-column: 1 / -1; grid-row: 2; }
  }
