// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
// ---- end shared helpers ----


// Page 1 answers -> state. Estimates in-hand pay from CTC and builds the cash-flow page.
const a   = $json;
const ctx = $('Evaluate Journey').first().json;
const cur = a.currency || 'INR';

const ctc = parseAmount(a.annual_ctc);
const target = parseAmount(a.target_amount);
const estimate = estimateInHand(ctc, cur);
const goalType = a.goal_type || 'Other';
const details = String(a.goal_details || '').trim();
const description = goalType === 'Other' ? (details || 'Other') : (details ? `${goalType} - ${details}` : goalType);

const state = {
  session_id: ctx.session_id,
  journey: ctx.journey,
  email: ctx.email,
  user_key: ctx.user_key,
  user_id: ctx.user_id,
  is_returning_user: ctx.is_returning_user,
  prefill: ctx.prefill,
  currency: cur,
  about: {
    user_name: String(a.user_name || '').trim(),
    age: parseAmount(a.age),
    annual_ctc: ctc,
    annual_ctc_raw: a.annual_ctc,
    estimated_monthly_in_hand: estimate,
  },
  goal: {
    goal_type: goalType,
    details,
    description,
    target_amount: target,
    target_amount_raw: a.target_amount,
    target_date: a.target_date,
  },
};

// ---------- the advisor's reaction + page 2 ----------
const name = firstName(state.about.user_name);
const months = monthsUntil(a.target_date);
const years = months !== null ? months / 12 : null;
const horizon = years === null || years <= 0 ? ''
  : years < 3 ? ' - a short runway, so we\'ll keep this money safe rather than chase returns'
  : years < 7 ? ' - a solid medium-term runway'
  : ' - a long runway, so time is on your side';
const yearsText = years === null || years <= 0 ? '' :
  years < 1 ? `about ${Math.max(1, months)} months away` : `about ${trim2(Math.round(years * 10) / 10)} years away`;

const goalLine = target
  ? `🎯 <strong>${esc(description)}</strong> - ${esc(fmtShort(target, cur))} by ${esc(monthYear(a.target_date))}${yearsText ? '. That\'s ' + yearsText : ''}${horizon}.`
  : `🎯 <strong>${esc(description)}</strong> by ${esc(monthYear(a.target_date))}.`;

let payLine;
if (estimate) {
  payLine = cur === 'INR'
    ? `💼 A CTC of <strong>${esc(fmtShort(ctc, cur))}</strong> usually lands around <strong>${esc(fmtShort(estimate, cur))} a month</strong> in your account after PF, professional tax and income tax (new regime). Does that sound right? If not, just correct it below.`
    : `💼 On a CTC of <strong>${esc(fmtShort(ctc, cur))}</strong> I've guessed roughly <strong>${esc(fmtShort(estimate, cur))} a month</strong> after tax - please correct it with your real take-home.`;
} else {
  payLine = '💼 I couldn\'t quite read your CTC - no problem, just tell me what actually reaches your bank account each month.';
}

const savedTakeHome = ctx.prefill.take_home;
const useSaved = ctx.journey === 'update' && savedTakeHome;

const form_fields = [
  { fieldType: 'html', html: bubble(`Lovely to meet you, ${esc(name)}! 🙌`, [goalLine, payLine,
      useSaved ? `Last time you told me your in-hand pay was <strong>${esc(fmtShort(parseAmount(savedTakeHome), cur))}</strong> - I've kept that below.` : '']) },
  { fieldLabel: 'Monthly in-hand salary', fieldName: 'take_home', fieldType: 'text', requiredField: true,
    placeholder: 'What reaches your bank account each month, e.g. 1.2L',
    defaultValue: useSaved ? savedTakeHome : shorthand(estimate, cur) },
  { fieldLabel: 'Monthly essential expenses', fieldName: 'expenses', fieldType: 'text', requiredField: true,
    placeholder: 'Rent, groceries, bills, school fees, commute - not loan EMIs',
    defaultValue: ctx.prefill.expenses },
];

return [{ json: {
  state,
  form_title: 'Step 2 of 5 · Money in, money out',
  form_description: 'Monthly figures. Shorthand like 85K or 1.2L is fine.',
  form_fields,
}}];

